fn cell(level: &GameLevel<'_>, state: BlockStateId) -> Option<(std::sync::Arc<Definition>, Cell)> {
    let state = level.registry.state(state)?;
    let def = fluid::for_block(&state.name)?;
    let value = state
        .properties
        .get("level")?
        .parse::<u8>()
        .ok()
        .filter(|n| *n <= 8)?;
    let c = Cell {
        fluid: def.id.clone(),
        level: value,
    };
    Some((def, c))
}

