fn sample(&self, p: Position) -> Sample {
    let at = pos(p);
    if p[1] < self.level.min_y() || p[1] >= self.level.max_y() {
        return Sample::Solid;
    }
    if !self.level.is_loaded(at) {
        return Sample::Unloaded;
    }
    let state = self.level.block_state(at);
    if self.level.behaviours.is_air(state) {
        return Sample::Air;
    }
    cell(self.level, state).map_or(Sample::Solid, |(_, c)| Sample::Fluid(c))
}

